import {openReportPreview} from './report-preview-dialog.js';
import {resolveQueueParish,queueParishFilter} from './parish-queue-scope.js';
import {isCertificateRequest} from './pending-queue.js';
import {reportRange} from './report-charts.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reportDateOnly(value){if(!value||!Number.isFinite(Date.parse(value)))return 'Not recorded';return new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Singapore',year:'numeric',month:'long',day:'numeric'}).format(new Date(value.length===10?value+'T12:00:00+08:00':value));}
export function buildParishReport({parish,rows,from,to,status='All',generated=new Date().toISOString()}){
 const certificates=rows.filter(isCertificateRequest),bookings=rows.length-certificates.length,types=new Map();for(const row of certificates)types.set(row.service_name||'Certificate',(types.get(row.service_name||'Certificate')||0)+1);
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Parish Report</title><style>@page{size:A4 portrait;margin:16mm}*{box-sizing:border-box}body{font:12px/1.6 Arial,sans-serif;color:#24364d;margin:0;background:#fff}header{text-align:center;border-bottom:2px solid #324d70;padding-bottom:16px;margin-bottom:20px}header p{margin:3px 0}h1{font-size:21px;margin:6px 0}h2{font-size:16px;margin:20px 0 8px}h3{font-size:14px;margin:5px 0} .eyebrow{font-size:10px;letter-spacing:2px;color:#6d7d91}.meta{font-size:11px;color:#64758b}.totals{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #ccd6e3;margin:18px 0}.totals div{padding:12px;border-right:1px solid #ccd6e3}.totals div:last-child{border:0}.totals span{display:block;color:#718197;font-size:11px}.totals strong{font-size:22px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{text-align:left;padding:9px 7px;border:1px solid #dce3ec;vertical-align:top;overflow-wrap:anywhere}th{background:#eff3f8;color:#405c7b;font-weight:600}thead{display:table-header-group}tr{break-inside:avoid}footer{margin-top:20px;padding-top:10px;border-top:1px solid #ccd6e3;font-size:10px;color:#7c8a9d}.empty{padding:16px;border:1px solid #dce3ec}.print-actions{display:flex;gap:10px;margin:16px 0}.print-actions button{padding:8px 16px;border:1px solid #ccd6e3;background:#f4f7fb;border-radius:5px;cursor:pointer}@media print{.print-actions{display:none}h2{break-after:avoid}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header><p class="eyebrow">PARISH OFFICE</p><h1>'+escape(parish)+'</h1><h3>Bookings and Certificate Requests Report</h3><p class="meta">Report date: '+escape(reportDateOnly(generated))+'</p><p class="meta">Period: '+escape(reportDateOnly(from))+' to '+escape(reportDateOnly(to))+' | Status: '+escape(status)+'</p></header><div class="totals"><div><span>Total requests</span><strong>'+rows.length+'</strong></div><div><span>Bookings</span><strong>'+bookings+'</strong></div><div><span>Certificate requests</span><strong>'+certificates.length+'</strong></div></div><h2>Certificate requests by type</h2>'+(!types.size?'<p>No certificate requests in this period.</p>':'<table><thead><tr><th>Certificate type</th><th>Requests</th></tr></thead><tbody>'+[...types].sort((a,b)=>b[1]-a[1]).map(([type,count])=>'<tr><td>'+escape(type)+'</td><td>'+count+'</td></tr>').join('')+'</tbody></table>')+'<h2>Request register</h2>'+(rows.length?'<table><thead><tr><th>Reference</th><th>Name</th><th>Service</th><th>Date submitted</th><th>Status</th></tr></thead><tbody>'+rows.map(row=>'<tr><td>'+escape(row.reference_number)+'</td><td>'+escape(row.client_name||[row.client_first_name,row.client_middle_name,row.client_last_name].filter(Boolean).join(' ')||'Not provided')+'</td><td>'+escape(row.service_name)+'</td><td>'+escape(reportDateOnly(row.created_at))+'</td><td>'+escape(row.booking_status||'Submitted')+'</td></tr>').join('')+'</tbody></table>':'<p class="empty">No requests match the selected period and status.</p>')+'<footer>Prepared by '+escape(parish)+' | '+rows.length+' request(s). Dates are shown in Philippine time; time of day is omitted.</footer><div class="print-actions"><button onclick="window.print()">Print / Save as PDF</button><button onclick="window.close()">Close</button></div></body></html>';
}
export async function printParishReport({session,fetchRows}){
 const popup=openReportPreview('Report preview');if(!popup){(await window.parishDialogs.alert('Please allow the report window to open, then try again.'));return;}
 popup.document.write('<!doctype html><title>Preparing Parish Report</title><p style="font:14px Arial;padding:24px">Loading parish report data...</p>');popup.document.close();
 try{
 const parish=await resolveQueueParish(session,(table,query)=>fetchRows(table,query,session.accessToken));
 const fields=document.querySelectorAll('.parish-reports-filters input[type=date]'),period=document.querySelector('.report-analytics-controls select')?.value||'month',anchor=document.querySelector('.report-analytics-controls input[type=date]')?.value||new Date().toISOString().slice(0,10),range=reportRange(period,anchor);
 const from=fields[0]?.value||range.start,to=fields[1]?.value||new Date(Date.parse(range.end+'T12:00:00Z')-86400000).toISOString().slice(0,10),status=document.querySelector('.parish-reports-filters select')?.value||'All';
 if(from>to)throw Error('The start date must be before the end date.');
 const rows=[],query=queueParishFilter(parish)+'&created_at=gte.'+encodeURIComponent(from+'T00:00:00+08:00')+'&created_at=lte.'+encodeURIComponent(to+'T23:59:59.999999+08:00')+(status!=='All'?'&booking_status=eq.'+encodeURIComponent(status):'');
 for(let offset=0;;offset+=1000){const batch=await fetchRows('diocese_service_bookings','select=id,reference_number,client_name,service_name,booking_status,created_at&'+query+'&order=created_at.asc,id.asc&limit=1000&offset='+offset,session.accessToken);if(!Array.isArray(batch))throw Error('Unexpected report response.');rows.push(...batch);if(batch.length<1000)break;}
 popup.document.open();popup.document.write(buildParishReport({parish:parish.parish_name,rows,from,to,status}));popup.document.close();await popup.document.fonts.ready;await new Promise(resolve=>setTimeout(resolve,200));popup.focus();
 }catch(error){popup.document.body.textContent='Could not prepare the report: '+(error.message||'Please try again.');}
}
